def _pin(data):return len(data),hashlib.sha256(data).hexdigest()

def transform_source(source,*,family):
    if type(source) is not bytes or type(family) is not str or family not in _RULES:
        raise ValueError('fixed B/C/E post-worker shipping source and explicit family required')
    before,after,spans,gaps,complement_pin=_RULES[family]
    if _pin(source)!=before:raise ValueError('exact post-worker shipping source required')
    parts=[];end=0
    for old_at,new_at,old,new in spans:
        if old_at<end or source[old_at:old_at+len(old)]!=old:raise ValueError('setter literal region differs')
        parts.extend((source[end:old_at],new));end=old_at+len(old)
    result=b''.join(parts)+source[end:];rest=[]
    for old_at,new_at,size,digest in gaps:
        a=source[old_at:old_at+size];b=result[new_at:new_at+size]
        if a!=b or _pin(a)!=(size,digest):raise ValueError('setter protected gap differs')
        rest.append(a)
    if _pin(b''.join(rest))!=complement_pin:raise ValueError('setter protected complement differs')
    inverse=[];end=0
    for old_at,new_at,old,new in spans:
        if new_at<end or result[new_at:new_at+len(new)]!=new:raise ValueError('setter result region differs')
        inverse.extend((result[end:new_at],old));end=new_at+len(new)
    if b''.join(inverse)+result[end:]!=source:raise ValueError('setter exact full inverse differs')
    if _pin(result)!=after:raise ValueError('fixed setter phase candidate differs')
    return result,dict(METADATA[family])
